targets.clientTransformScript:
javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        table: event.payload.cell.metadata.openRecordMetadata.table,
        sysId: event.payload.cell.metadata.openRecordMetadata.sysId,
    };
})

script.inlineScript:
